CREATE DATABASE IF NOT EXISTS homescope CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE homescope;
CREATE TABLE IF NOT EXISTS agents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,registration_no VARCHAR(30) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL,avatar_url VARCHAR(500) NOT NULL);
CREATE TABLE IF NOT EXISTS listings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id VARCHAR(80) NOT NULL UNIQUE,agent_id BIGINT UNSIGNED NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,address VARCHAR(255) NOT NULL,district VARCHAR(8) NOT NULL,property_type ENUM('Condo','HDB','Apartment','Landed') NOT NULL,tenure ENUM('99-year','999-year','Freehold') NOT NULL,price INT UNSIGNED NOT NULL,psf INT UNSIGNED NOT NULL,bedrooms TINYINT UNSIGNED NOT NULL,bathrooms TINYINT UNSIGNED NOT NULL,floor_area INT UNSIGNED NOT NULL,location POINT NOT NULL SRID 4326,mrt_name VARCHAR(100) NOT NULL,mrt_distance SMALLINT UNSIGNED NOT NULL,image_url VARCHAR(500) NOT NULL,images_json JSON NOT NULL,amenities_json JSON NOT NULL,description TEXT NOT NULL,is_featured BOOLEAN NOT NULL DEFAULT FALSE,status ENUM('draft','published','archived') NOT NULL DEFAULT 'published',listed_at DATETIME NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,SPATIAL INDEX idx_location(location),INDEX idx_search(status,property_type,district,price,bedrooms,listed_at,id),INDEX idx_sort_price(status,price,id),CONSTRAINT fk_listing_agent FOREIGN KEY(agent_id) REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,transaction_month DATE NOT NULL,price INT UNSIGNED NOT NULL,psf INT UNSIGNED NOT NULL,storey_range VARCHAR(30) NULL,floor_area_sqm DECIMAL(7,2) NULL,flat_model VARCHAR(80) NULL,data_source ENUM('hdb','modelled') NOT NULL DEFAULT 'modelled',UNIQUE KEY uq_listing_month(listing_id,transaction_month),CONSTRAINT fk_tx_listing FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refresh_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_refresh(token_hash,expires_at),CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS favourites(user_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,listing_id),CONSTRAINT fk_fav_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_fav_listing FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS saved_searches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,filters_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_search_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
